def compatibility_probe(payload):
    PreviousOrderInput.model_validate(payload)
    previous_accepts = True
    try:
        RevisedOrderInput.model_validate(payload)
        revised_accepts = True
    except ValidationError:
        revised_accepts = False
    client_breaking = True
    repaired = CompatibleOrderInput.model_validate(payload)
